\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Neural Circuit / Neuroscience Theme ──
% Deep navy background, electric blue + teal + warm gold accents
\definecolor{primary}{HTML}{1E3A5F}      % deep navy
\definecolor{secondary}{HTML}{0EA5E9}    % electric blue
\definecolor{accent}{HTML}{14B8A6}       % teal
\definecolor{gold}{HTML}{F59E0B}          % warm gold
\definecolor{bgposter}{HTML}{0B1120}      % very dark navy (poster bg)
\definecolor{redbg}{HTML}{0F2942}        % card backgrounds (tinted navy)
\definecolor{bluebg}{HTML}{0F2942}
\definecolor{darkbg}{HTML}{0D1F35}
\definecolor{redtitlebg}{HTML}{162D4A}
\definecolor{bluetitlebg}{HTML}{162D4A}
\definecolor{darktitlebg}{HTML}{162D4A}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textlight}{HTML}{CBD5E1}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{stathighlight}{HTML}{1E3A5F}
\definecolor{statnumberbg}{HTML}{0F2942}

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\textbullet}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{gold}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth,height=#1\linewidth,keepaspectratio]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{gold},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={gold!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary,
    borderline west={6pt}{0pt}{gold},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{78}{94}\selectfont\bfseries Mapping Neural Circuit Architecture}\\[10pt]
  {\fontsize{34}{42}\selectfont Advances in Brain Connectivity Analysis}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{textlight} \textbf{Nature}, 2024 --- DOI: 10.1038/s41586-024-07487-w}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!15!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \fcolorbox{secondary!35}{statnumberbg}{\parbox{0.22\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{60}{72}\selectfont\bfseries\color{secondary} 125K}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textlight} Neurons Mapped}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} ~125,000 neurons}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} reconstructed}\vspace{8pt}%
  }}\hfill
  \fcolorbox{accent!35}{statnumberbg}{\parbox{0.22\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{60}{72}\selectfont\bfseries\color{accent} 54M}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textlight} Synaptic Connections}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} ~54 million synapses}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} identified \& catalogued}\vspace{8pt}%
  }}\hfill
  \fcolorbox{gold!35}{statnumberbg}{\parbox{0.22\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{60}{72}\selectfont\bfseries\color{gold} 37}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textlight} Circuit Motifs}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} Distinct recurring}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} connectivity motifs}\vspace{8pt}%
  }}\hfill
  \fcolorbox{secondary!35}{statnumberbg}{\parbox{0.22\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{60}{72}\selectfont\bfseries\color{secondary} 94.2\%}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textlight} Classification Acc.}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} Automated neuron-type}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textgray} classification}\vspace{8pt}%
  }}
}

% ══ BACKGROUND & MOTIVATION ══
\posterbox[redcard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Understanding brain function requires detailed connectivity maps
    \item Classical neuroanatomy lacked resolution to capture complete circuits
    \item Large-scale connectomics now bridges structure and function
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!25}{\parbox{0.92\linewidth}{%
    \fontsize{28}{36}\selectfont\color{textlight}
    This Nature 2024 study reconstructs neural circuits at \textbf{unprecedented scale}, revealing new organizational principles.
  }}
}

% ══ METHODOLOGY ══
\posterbox[darkcard, title={Methodology}
]{name=method, column=2, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Serial-section EM at 4nm × 4nm × 30nm resolution
    \item Deep learning for automated neuron tracing
    \item CNN synapse classifier (94.2\% accuracy)
    \item Graph-theoretic motif detection
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textlight}
    Pipeline: EM Imaging $\rightarrow$ Segmentation $\rightarrow$ Synapse Detection $\rightarrow$ Circuit Analysis
  }}
}

% ══ KEY FINDINGS (LEFT) ══
\posterbox[bluecard, title={Key Findings}
]{name=findings1, column=3, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{37 distinct motifs} suggest modular wiring logic
    \item \textbf{Hub neurons}: 3.5\% of population $\rightarrow$ 28\% of synaptic output
    \item \textbf{Layer 5}: 4.7:1 recurrent-to-feedforward ratio
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textlight}
    Inhibitory interneurons showed \textbf{6.2× higher} wiring specificity than excitatory neurons
  }}
}

% ══ CONTRIBUTIONS ══
\posterbox[redcard, title={Contributions}
]{name=contributions, column=1, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item Largest connectome dataset at this resolution
    \item 37 novel circuit motifs discovered
    \item Quantified layer-specific wiring rules
    \item Open-access dataset \& analysis tools
  \end{enumerate}
}

% ══ CIRCUIT ANALYSIS DETAILS ══
\posterbox[darkcard, title={Circuit Architecture}
]{name=circuit, column=2, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Cell-type-specific wiring patterns mapped
    \item Modular motif vocabulary identified
    \item Non-uniform influence distribution characterized
  \end{itemize}
  \vspace{4pt}
  \colorbox{gold!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textlight}
    Like logic gates in digital circuits --- the brain uses a \textbf{finite vocabulary} of circuit elements.
  }}
}

% ══ KEY FINDINGS 2 ══
\posterbox[bluecard, title={Quantitative Results}
]{name=findings2, column=3, between=row11 and row16}{
  \fontsize{32}{42}\selectfont
  \begin{tabular}[t]{@{}l@{: }r@{}}
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\color{textlight} Connectivity motifs & \fontsize{26}{34}\selectfont\color{secondary}\textbf{37} \\
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\color{textlight} Hub neuron fraction & \fontsize{26}{34}\selectfont\color{secondary}\textbf{3.5\%} \\
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\color{textlight} Synaptic output share & \fontsize{26}{34}\selectfont\color{secondary}\textbf{28\%} \\
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\color{textlight} Layer 5 recurrent ratio & \fontsize{26}{34}\selectfont\color{accent}\textbf{4.7:1} \\
    \rowcolor{primary!20}
    \fontsize{26}{34}\selectfont\color{textlight} Inhibitory specificity & \fontsize{26}{34}\selectfont\color{gold}\textbf{6.2×}
  \end{tabular}
  \vspace{4pt}
}

% ══ IMPLICATIONS ══
\posterbox[redcard, title={Implications \& Future Directions}
]{name=implications, column=1, between=row16 and row20}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Reshapes understanding of cortical computation
    \item Hub neurons explain lesion spread effects
    \item Relevant to neurological disease \& BCI design
    \item Extension to additional brain regions underway
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textlight}
    Goal: Build a complete wiring diagram of the mammalian brain.
  }}
}

% ══ METHODOLOGY PIPELINE ══
\posterbox[darkcard, title={Connectomics Pipeline}
]{name=pipeline, column=2, between=row16 and row20}{
  \fontsize{32}{42}\selectfont
  \colorbox{primary!25}{\parbox{0.92\linewidth}{%
    \centering
    {\fontsize{28}{36}\selectfont\color{secondary} EM Imaging}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} $\downarrow$}\\[2pt]
    {\fontsize{28}{36}\selectfont\color{secondary} Segmentation}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} $\downarrow$}\\[2pt]
    {\fontsize{28}{36}\selectfont\color{accent} Synapse Detection}\\[2pt]
    {\fontsize{24}{30}\selectfont\color{textgray} $\downarrow$}\\[2pt]
    {\fontsize{28}{36}\selectfont\color{gold} Circuit Analysis}
  }}
  \vspace{4pt}
}

% ══ KEY TAKEAWAYS ══
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row16 and row20}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Scale} matters: 125K neurons, 54M synapses
    \item \textbf{Precision}: 94.2\% automated classification
    \item \textbf{Novelty}: 37 new circuit motifs
    \item \textbf{Open science}: dataset publicly available
  \end{itemize}
  \vspace{4pt}
  {\fontsize{26}{34}\selectfont\color{textlight} \textbf{Nature} 2024 --- DOI: 10.1038/s41586-024-07487-w}
}

\end{tcbposter}
\end{document}

